import 'package:shule_direct/core/constants/import_files.dart';import 'package:shule_direct/features/chat/presentation/screens/widgets/message_options_sheet.dart';class ChatScreen extends StatelessWidget {  final int conversationId;  final String groupName;  const ChatScreen({    super.key,    required this.conversationId,    required this.groupName,  });  @override  Widget build(BuildContext context) {    return BlocProvider(      create: (_) => sl<ChatCubit>()..init(conversationId),      child: _ChatScreenBody(        conversationId: conversationId,        groupName: groupName,      ),    );  }}class _ChatScreenBody extends StatefulWidget {  final int conversationId;  final String groupName;  const _ChatScreenBody({    required this.conversationId,    required this.groupName,  });  @override  State<_ChatScreenBody> createState() => _ChatScreenBodyState();}class _ChatScreenBodyState extends State<_ChatScreenBody> {  final _scrollController = ScrollController();  final _inputFocusNode = FocusNode();  int _lastTailMessageId = 0;  String _lastTailContent = '';  bool _scrollToBottomOnNextLoad = true;  bool _isLoadingOlder = false;  @override  void initState() {    super.initState();    _scrollController.addListener(_onScroll);  }  void _onScroll() {    if (!_scrollController.hasClients || _isLoadingOlder) return;    if (_scrollController.position.pixels > 120) return;    final cubit = context.read<ChatCubit>();    final state = cubit.state;    if (state is! ChatLoaded || !state.hasMore || state.isLoadingMore) return;    _isLoadingOlder = true;    cubit.loadMoreMessages().whenComplete(() {      if (mounted) _isLoadingOlder = false;    });  }  bool _hasNewMessageAtBottom(ChatLoaded state) {    if (state.messages.isEmpty) return false;    final tail = state.messages.last;    return tail.id != _lastTailMessageId || tail.content != _lastTailContent;  }  void _updateTailTracker(ChatLoaded state) {    if (state.messages.isEmpty) {      _lastTailMessageId = 0;      _lastTailContent = '';      return;    }    final tail = state.messages.last;    _lastTailMessageId = tail.id;    _lastTailContent = tail.content;  }  void _scrollToBottom({bool instant = false}) {    WidgetsBinding.instance.addPostFrameCallback((_) {      WidgetsBinding.instance.addPostFrameCallback((_) {        if (!_scrollController.hasClients) return;        final max = _scrollController.position.maxScrollExtent;        if (instant) {          _scrollController.jumpTo(max);        } else {          _scrollController.animateTo(            max,            duration: const Duration(milliseconds: 300),            curve: Curves.easeOut,          );        }      });    });  }  Future<String?> _handleSend(String text) async {    if (text.trim().isEmpty) {      return 'Message cannot be empty.';    }    final cubit = context.read<ChatCubit>();    final state = cubit.state;    final replyId = state is ChatLoaded ? state.replyingTo?.id : null;    final error = await cubit.sendMessage(      content: text,      replyTo: replyId,    );    if (error != null && mounted) {      ScaffoldMessenger.of(context).showSnackBar(        SnackBar(          content: Text(error),          backgroundColor: AppColors.errorColor,        ),      );    }    return error;  }  void _onMessageMoreTap(BuildContext context, MessageEntity message) {    if (message.id <= 0 || message.type == 'system') return;    showMessageOptionsSheet(      context: context,      onReply: () {        context.read<ChatCubit>().setReplyingTo(message);        _inputFocusNode.requestFocus();        _scrollToBottom();      },      onDelete: message.isMe          ? () => context.read<ChatCubit>().deleteMessage(message.id)          : null,    );  }  @override  void dispose() {    _inputFocusNode.dispose();    _scrollController.dispose();    super.dispose();  }  @override  Widget build(BuildContext context) {    return AppStatusBarScaffold.primary(      appBar: const CommonAppbar(),      backgroundColor: Colors.white,      body: BlocConsumer<ChatCubit, ChatState>(        listener: (context, state) {          if (state is ChatLoading) {            _scrollToBottomOnNextLoad = true;            _lastTailMessageId = 0;            _lastTailContent = '';          }          if (state is ChatLoaded) {            if (_scrollToBottomOnNextLoad && state.messages.isNotEmpty) {              _scrollToBottomOnNextLoad = false;              _updateTailTracker(state);              _scrollToBottom(instant: true);            } else if (_hasNewMessageAtBottom(state)) {              _updateTailTracker(state);              _scrollToBottom();            } else {              _updateTailTracker(state);            }          }        },        builder: (context, state) {          if (state is ChatLoading) {            return const Center(              child: CircularProgressIndicator(color: AppColors.primary),            );          }          if (state is ChatError) {            return Center(              child: Column(                mainAxisSize: MainAxisSize.min,                children: [                  AppText(                    state.message,                    fontSize: 13,                    color: AppColors.errorColor,                  ),                  const SizedBox(height: 12),                  AppPrimaryButton(                    label: 'Retry',                    onPressed: () =>                        context.read<ChatCubit>().init(widget.conversationId),                  ),                ],              ),            );          }          if (state is ChatLoaded) {            return Column(              children: [                ChatGroupHeader(                  groupName: widget.groupName,                  onlineCount: 20,                  onBack: () => Navigator.of(context).pop(),                ),                if (state.isLoadingMore)                  const Padding(                    padding: EdgeInsets.symmetric(vertical: 8),                    child: SizedBox(                      width: 22,                      height: 22,                      child: CircularProgressIndicator(                        strokeWidth: 2,                        color: AppColors.primary,                      ),                    ),                  ),                Expanded(                  child: state.messages.isEmpty                      ? const Center(                          child: AppText(                            'No messages yet. Say hello',                            fontSize: 13,                            color: AppColors.textSecondary,                          ),                        )                      : ListView.builder(                          controller: _scrollController,                          padding: const EdgeInsets.symmetric(vertical: 8),                          itemCount: state.messages.length,                          itemBuilder: (context, index) {                            final msg = state.messages[index];                            if (msg.type == 'system') {                              return SystemMessage(text: msg.content);                            }                            return MessageBubble(                              message: msg,                              onMoreTap: msg.id > 0 && msg.type != 'system'                                  ? () => _onMessageMoreTap(context, msg)                                  : null,                            );                          },                        ),                ),                if (state.replyingTo != null)                  ReplyPreview(                    replyingTo: state.replyingTo!,                    onCancel: () => context.read<ChatCubit>().clearReply(),                  ),                MessageInputBar(                  focusNode: _inputFocusNode,                  onSend: _handleSend,                ),              ],            );          }          return const SizedBox.shrink();        },      ),    );  }}